import React, { useState } from 'react';     
import './LoginPage.css';

const LoginPage = () => {
  const [email, setEmail] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log('Email submitted:', email);
  };

  const handleStaffAdminLogin = () => {
    console.log('Navigate to staff/admin login');
    // Có thể navigate đến trang login riêng cho staff/admin
  };

  return (
    <div className="login-page">
      <div className="login-container">
        <div className="logo-section">
          <img src="/LEAF.png" alt="LEAF" className="logo" />
        </div>
        
        <div className="login-content">
          <h1 className="login-title">Đăng nhập</h1>
          <p className="login-description">
            Nhập email của bạn để chúng tôi gửi cho bạn mã xác minh
          </p>
          
          <form onSubmit={handleSubmit} className="login-form">
            <input
              type="email"
              placeholder="Email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="email-input"
              required
            />
            
            <div className="user-type-section">
              <label className="user-type-label">Loại tài khoản:</label>
              <div className="user-type-options">
                <label className="radio-option">
                  <input
                    type="radio"
                    name="userType"
                    value="staff"
                    checked={userType === 'staff'}
                    onChange={(e) => setUserType(e.target.value)}
                  />
                  <span className="radio-text">Staff</span>
                </label>
                <label className="radio-option">
                  <input
                    type="radio"
                    name="userType"
                    value="admin"
                    checked={userType === 'admin'}
                    onChange={(e) => setUserType(e.target.value)}
                  />
                  <span className="radio-text">Admin</span>
                </label>
              </div>
            </div>
            
            <button type="submit" className="continue-button">
              Tiếp tục
            </button>
          </form>
          
          <div className="links-section">
            <a href="#" className="policy-link">Chính sách quyền riêng tư</a>
            <a href="#" className="terms-link">Điều khoản dịch vụ</a>
          </div>
        </div>
      </div>
    </div>
  );
};

export default LoginPage;
